const f=n=>n*Math.PI/180;function x(n,t){return[f(n[0]-t[0])*Math.cos(f(t[1]))*6371e3,f(n[1]-t[1])*6371e3]}function v(n,t){if(!Array.isArray(t)||t.length<2)return{offRouteM:1/0,travelledM:0,remainingM:0,totalM:0};let a={dist:1/0,segment:0,t:0};const o=[];for(let e=0;e<t.length-1;e+=1){const r=t[e],[c,M]=x(t[e+1],r),[h,d]=x(n,r),l=c*c+M*M;o.push(Math.sqrt(l));const u=l>0?Math.max(0,Math.min(1,(h*c+d*M)/l)):0,m=Math.hypot(h-u*c,d-u*M);m<a.dist&&(a={dist:m,segment:e,t:u})}const i=o.reduce((e,r)=>e+r,0),s=o.slice(0,a.segment).reduce((e,r)=>e+r,0)+o[a.segment]*a.t;return{offRouteM:a.dist,travelledM:s,remainingM:Math.max(0,i-s),totalM:i}}function p(n,t,a=[]){var i;const o=v(n,t);for(const s of a){if(!((i=s.maneuver)!=null&&i.location)||s.maneuver.type==="depart")continue;const e=v(s.maneuver.location,t).travelledM;if(e>o.travelledM+5)return{step:s,distanceM:e-o.travelledM,here:o}}return{step:a[a.length-1]||null,distanceM:o.remainingM,here:o}}const R=n=>n>=1e3?`${(n/1e3).toFixed(n>=1e4?0:1)} km`:`${Math.max(0,Math.round(n/10)*10)} m`,A=n=>{const t=Math.max(1,Math.round(n/60));return t>=60?`${Math.floor(t/60)} h ${t%60} min`:`${t} min`};export{R as a,A as f,p as n};
